public class OrderAggregateRoot {
    private final OrderId id;
    private OrderStatus status;
    private final List<OrderLineItem> lineItems = new ArrayList<>();

    public void addItem(ProductCatalogId productId, int quantity, Money price) {
        if (this.status != OrderStatus.DRAFT) {
            throw new IllegalStateException("Cannot modify an order that is no longer in draft status.");
        }
        this.lineItems.add(new OrderLineItem(productId, quantity, price));
    }

    public OrderId getId() { return id; }
    public List<OrderLineItem> getLineItems() { return Collections.unmodifiableList(lineItems); }
}
